#include <vector>
#include <algorithm>

class Solution {
public:
    int minUnlockedIndices(std::vector<int>& nums, std::vector<int>& locked) {
        int n = nums.size();
        int first2 = -1, first3 = -1;
        int last1 = -1, last2 = -1;

        for (int i = 0; i < n; ++i) {
            if (nums[i] == 2 && first2 == -1) first2 = i;
            if (nums[i] == 3 && first3 == -1) first3 = i;
            if (nums[i] == 1) last1 = i;
            if (nums[i] == 2) last2 = i;
        }

        if (first3 != -1 && last1 != -1 && first3 < last1) {
            return -1;
        }

        int ans = 0;
        if (first2 != -1 && last1 != -1 && first2 < last1) {
            for (int i = first2; i < last1; ++i) {
                if (locked[i] == 1) ++ans;
            }
        }
        if (first3 != -1 && last2 != -1 && first3 < last2) {
            for (int i = first3; i < last2; ++i) {
                if (locked[i] == 1) ++ans;
            }
        }
        return ans;
    }
};

class Solution {
    public int minUnlockedIndices(int[] nums, int[] locked) {
        int n = nums.length;
        int first2 = -1, first3 = -1;
        int last1 = -1, last2 = -1;

        for (int i = 0; i < n; i++) {
            if (nums[i] == 2 && first2 == -1) first2 = i;
            if (nums[i] == 3 && first3 == -1) first3 = i;
            if (nums[i] == 1) last1 = i;
            if (nums[i] == 2) last2 = i;
        }

        if (first3 != -1 && last1 != -1 && first3 < last1) {
            return -1;
        }

        int ans = 0;
        if (first2 != -1 && last1 != -1 && first2 < last1) {
            for (int i = first2; i < last1; i++) {
                if (locked[i] == 1) ans++;
            }
        }
        if (first3 != -1 && last2 != -1 && first3 < last2) {
            for (int i = first3; i < last2; i++) {
                if (locked[i] == 1) ans++;
            }
        }
        return ans;
    }
}

var minUnlockedIndices = function(nums, locked) {
    const n = nums.length;
    let first2 = -1, first3 = -1;
    let last1 = -1, last2 = -1;

    for (let i = 0; i < n; i++) {
        if (nums[i] === 2 && first2 === -1) first2 = i;
        if (nums[i] === 3 && first3 === -1) first3 = i;
        if (nums[i] === 1) last1 = i;
        if (nums[i] === 2) last2 = i;
    }

    if (first3 !== -1 && last1 !== -1 && first3 < last1) {
        return -1;
